// main.zig — swscale candidate: pixel-format conversion and scaling.
//
// The generic path mirrors FFmpeg's scalar pipeline (input conversion ->
// horizontal filter into 15-bit intermediates -> vertical filter / output),
// integer-exact, so results track the reference.  Same-size special cases
// mirror FFmpeg's unscaled converters.  Hot paths use @Vector SIMD (fast.zig).

const std = @import("std");
const fast = @import("fast.zig");
const alloc = std.heap.c_allocator;

pub const YUV420P = 0;
pub const YUV422P = 1;
pub const YUV444P = 2;
pub const NV12 = 3;
pub const NV21 = 4;
pub const RGB24 = 5;
pub const BGR24 = 6;
pub const RGBA = 7;
pub const BGRA = 8;
pub const GRAY8 = 9;

const ALGO_NEAREST = 0;
const ALGO_BILINEAR = 1;
const ALGO_BICUBIC = 2;

pub fn isRGB(f: i32) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isGray(f: i32) bool {
    return f == GRAY8;
}
fn isPlanarYUV(f: i32) bool {
    return f <= NV21;
}
fn isSemiPlanar(f: i32) bool {
    return f == NV12 or f == NV21;
}
fn hasAlpha(f: i32) bool {
    return f == RGBA or f == BGRA;
}
pub fn rgbBpp(f: i32) usize {
    return if (f == RGB24 or f == BGR24) 3 else 4;
}
// byte offsets of R, G, B within a packed pixel
pub fn rOff(f: i32) usize {
    return if (f == RGB24 or f == RGBA) 0 else 2;
}
pub fn bOff(f: i32) usize {
    return if (f == RGB24 or f == RGBA) 2 else 0;
}
fn hsub(f: i32) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn vsub(f: i32) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn ceilShift(x: i32, s: u5) i32 {
    return -((-x) >> s);
}

// ── rgb->yuv coefficients (FFmpeg default BT.601 table, RGB2YUV_SHIFT 15) ──
pub const RY: i32 = @intFromFloat(0.299 * 219.0 / 255.0 * 32768.0 + 0.5);
pub const GY: i32 = @intFromFloat(0.587 * 219.0 / 255.0 * 32768.0 + 0.5);
pub const BY: i32 = @intFromFloat(0.114 * 219.0 / 255.0 * 32768.0 + 0.5);
pub const RU: i32 = -@as(i32, @intFromFloat(0.169 * 224.0 / 255.0 * 32768.0 + 0.5));
pub const GU: i32 = -@as(i32, @intFromFloat(0.331 * 224.0 / 255.0 * 32768.0 + 0.5));
pub const BU: i32 = @intFromFloat(0.500 * 224.0 / 255.0 * 32768.0 + 0.5);
pub const RV: i32 = @intFromFloat(0.500 * 224.0 / 255.0 * 32768.0 + 0.5);
pub const GV: i32 = -@as(i32, @intFromFloat(0.419 * 224.0 / 255.0 * 32768.0 + 0.5));
pub const BV: i32 = -@as(i32, @intFromFloat(0.081 * 224.0 / 255.0 * 32768.0 + 0.5));

// ── filters ─────────────────────────────────────────────────────────────────
pub const Filter = struct {
    size: usize,
    pos: []i32,
    coef: []i16,
};

fn av_log2(v: i32) i32 {
    if (v <= 0) return 0;
    return 31 - @as(i32, @clz(@as(u32, @intCast(v))));
}

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

fn absI64(x: i64) i64 {
    return if (x < 0) -x else x;
}

fn initFilter(xInc: i32, srcW: i32, dstW: i32, one: i64, algo: i32, srcPos: i32, dstPos: i32) !Filter {
    const dW: usize = @intCast(dstW);
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(av_log2(@divTrunc(srcW, dstW)), 8));
    var pos = try alloc.alloc(i32, dW);
    var filterSize: usize = 1;
    var filter: []i64 = undefined;

    const xi: i64 = xInc;
    if (@abs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dW);
        for (0..dW) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == ALGO_NEAREST) {
        filterSize = 1;
        filter = try alloc.alloc(i64, dW);
        var xDstInSrc: i64 = ((@as(i64, dstPos) * xi) >> 8) - ((@as(i64, srcPos) * 0x8000) >> 7);
        for (0..dW) |i| {
            const xx: i64 = (xDstInSrc + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xi;
        }
    } else {
        const sizeFactor: i32 = if (algo == ALGO_BICUBIC) 4 else 2;
        var fs: i32 = undefined;
        if (xInc <= 1 << 16) {
            fs = 1 + sizeFactor;
        } else {
            fs = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        fs = @min(fs, srcW - 2);
        fs = @max(fs, 1);
        filterSize = @intCast(fs);
        filter = try alloc.alloc(i64, dW * filterSize);
        var xDstInSrc: i64 = ((@as(i64, dstPos) * xi) >> 7) - ((@as(i64, srcPos) * 0x10000) >> 7);
        const B: i64 = 0;
        const C: i64 = @intFromFloat(0.6 * @as(f64, 1 << 24));
        for (0..dW) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - @as(i64, fs - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..filterSize) |j| {
                var d: i64 = absI64(xx * (1 << 17) - xDstInSrc) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (algo == ALGO_BICUBIC) {
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * filterSize + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xi;
        }
    }

    // reduce filter size (step 1)
    const f2s = filterSize;
    const filter2 = filter;
    var minFilterSize: usize = 0;
    const cutLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    var ii: isize = @as(isize, @intCast(dW)) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: usize = f2s;
        var cutOff: i64 = 0;
        var j: usize = 0;
        while (j < f2s) : (j += 1) {
            cutOff += absI64(filter2[i * f2s]);
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            if (i < dW - 1 and pos[i] >= pos[i + 1]) break;
            var k: usize = 1;
            while (k < f2s) : (k += 1) filter2[i * f2s + k - 1] = filter2[i * f2s + k];
            filter2[i * f2s + k - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var jj: usize = f2s - 1;
        while (jj > 0) : (jj -= 1) {
            cutOff += absI64(filter2[i * f2s + jj]);
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    filterSize = minFilterSize;
    var flt = try alloc.alloc(i64, dW * filterSize);
    defer alloc.free(flt);
    for (0..dW) |i| {
        for (0..filterSize) |j| {
            flt[i * filterSize + j] = if (j >= f2s) 0 else filter2[i * f2s + j];
        }
    }
    alloc.free(filter2);

    // fix borders
    const fsI: i32 = @intCast(filterSize);
    for (0..dW) |i| {
        const row = flt[i * filterSize .. (i + 1) * filterSize];
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < filterSize) : (j += 1) {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                row[left] += row[j];
                row[j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + fsI > srcW) {
            const shift: i32 = pos[i] + @min(fsI - srcW, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(filterSize)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (pos[i] + @as(i32, @intCast(j)) >= srcW) {
                    acc += row[ju];
                    row[ju] = 0;
                }
            }
            j = @as(isize, @intCast(filterSize)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    row[ju] = 0;
                } else {
                    row[ju] = row[@intCast(j - shift)];
                }
            }
            pos[i] -= shift;
            row[@intCast(srcW - 1 - pos[i])] += acc;
        }
    }

    // normalize
    var coef = try alloc.alloc(i16, dW * filterSize);
    for (0..dW) |i| {
        var err: i64 = 0;
        var sum: i64 = 0;
        for (0..filterSize) |j| sum += flt[i * filterSize + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        for (0..filterSize) |j| {
            const v = flt[i * filterSize + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * filterSize + j] = @intCast(intV);
            err = v - intV * sum;
        }
    }
    _ = &coef;
    _ = &pos;
    return .{ .size = filterSize, .pos = pos, .coef = coef };
}

fn freeFilter(f: *Filter) void {
    alloc.free(f.pos);
    alloc.free(f.coef);
}

// ── yuv->rgb tables ──────────────────────────────────────────────────────────
pub const RgbTables = struct {
    ytab: [2048]u8,
    rv: [256]i32,
    gu: [256]i32,
    gv: [256]i32,
    bu: [256]i32,
    // full-chroma output coefficients
    y_off: i32,
    y_coeff: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,
};

fn roundToInt16(f: i64) i32 {
    const r: i64 = (f + (1 << 15)) >> 16;
    if (r < -0x7FFF) return -32768;
    if (r > 0x7FFF) return 0x7FFF;
    return @intCast(r);
}

fn initRgbTables(t: *RgbTables, fullRange: bool) void {
    var crv: i64 = 104597;
    var cbu: i64 = 132201;
    var cgu: i64 = -25675;
    var cgv: i64 = -53279;
    var cy: i64 = 1 << 16;
    var oy: i64 = 0;
    if (!fullRange) {
        cy = @divTrunc(cy * 255, 219);
        oy = 16 << 16;
    } else {
        crv = @divTrunc(crv * 224, 255);
        cbu = @divTrunc(cbu * 224, 255);
        cgu = @divTrunc(cgu * 224, 255);
        cgv = @divTrunc(cgv * 224, 255);
    }
    t.y_coeff = roundToInt16(cy * (1 << 13));
    t.y_off = roundToInt16(oy * (1 << 9));
    t.v2r = roundToInt16(crv * (1 << 13));
    t.v2g = roundToInt16(cgv * (1 << 13));
    t.u2g = roundToInt16(cgu * (1 << 13));
    t.u2b = roundToInt16(cbu * (1 << 13));
    crv = @divTrunc(crv * (1 << 16) + 0x8000, cy);
    cbu = @divTrunc(cbu * (1 << 16) + 0x8000, cy);
    cgu = @divTrunc(cgu * (1 << 16) + 0x8000, cy);
    cgv = @divTrunc(cgv * (1 << 16) + 0x8000, cy);
    var yb: i64 = -(384 << 16) - 512 * cy - oy;
    for (0..2048) |i| {
        const v = (yb + 0x8000) >> 16;
        t.ytab[i] = @intCast(std.math.clamp(v, 0, 255));
        yb += cy;
    }
    const yoffs: i64 = (if (fullRange) @as(i64, 384) else 326) + 512;
    for (0..256) |i| {
        const c: i64 = @intCast(i);
        t.rv[i] = @intCast(yoffs + ((c * crv) >> 16) - (crv >> 9));
        t.gu[i] = @intCast(yoffs + ((c * cgu) >> 16) - (cgu >> 9));
        t.gv[i] = @intCast(((c * cgv) >> 16) - (cgv >> 9));
        t.bu[i] = @intCast(yoffs + ((c * cbu) >> 16) - (cbu >> 9));
    }
}

inline fn clipU8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}
inline fn clipIdx(v: i32) usize {
    return @intCast(std.math.clamp(v, 0, 2047));
}

// ── context ─────────────────────────────────────────────────────────────────
const Mode = enum { generic, yuv2rgb, rgb2rgb, p2nv, nv2p, bgr24yv12 };

pub const Ctx = struct {
    srcW: i32,
    srcH: i32,
    srcF: i32,
    dstW: i32,
    dstH: i32,
    dstF: i32,
    algo: i32,
    mode: Mode,
    tabs: RgbTables,

    // generic
    fullChrOut: bool = false,
    chrSrcHSub: u5 = 0,
    chrSrcVSub: u5 = 0,
    chrDstHSub: u5 = 0,
    chrDstVSub: u5 = 0,
    chrSrcW: i32 = 0,
    chrSrcH: i32 = 0,
    chrDstW: i32 = 0,
    chrDstH: i32 = 0,
    needsHc: bool = false,
    needAlpha: bool = false,
    lumRange: i32 = 0, // 0 none, 1 to jpeg, 2 from jpeg
    hLum: Filter = undefined,
    hChr: Filter = undefined,
    vLum: Filter = undefined,
    vChr: Filter = undefined,
    lumBuf: []i16 = &.{},
    alpBuf: []i16 = &.{},
    chrUBuf: []i16 = &.{},
    chrVBuf: []i16 = &.{},
    tmp0: []u16 = &.{},
    tmp1: []u16 = &.{},
    tmp2: []u16 = &.{},
    tmpB0: []u8 = &.{},
    tmpB1: []u8 = &.{},
    lumStride: usize = 0,
    chrStride: usize = 0,
    hasFilters: bool = false,
    fastId: i32 = 0,
};

fn createCtx(srcW: i32, srcH: i32, srcF: i32, dstW: i32, dstH: i32, dstF: i32, algo: i32) !*Ctx {
    if (srcF < 0 or srcF > 9 or dstF < 0 or dstF > 9 or algo < 0 or algo > 2) return error.Bad;
    if (srcW < 1 or srcH < 1 or dstW < 1 or dstH < 1) return error.Bad;
    const c = try alloc.create(Ctx);
    c.* = .{ .srcW = srcW, .srcH = srcH, .srcF = srcF, .dstW = dstW, .dstH = dstH, .dstF = dstF, .algo = algo, .mode = .generic, .tabs = undefined };

    const srcRange: bool = isGray(srcF);
    const dstRange: bool = isGray(dstF);
    initRgbTables(&c.tabs, srcRange);

    const unscaled = srcW == dstW and srcH == dstH;
    if (unscaled and (srcRange == dstRange or isRGB(dstF))) {
        if (srcF == YUV420P and (dstF == NV12 or dstF == NV21)) c.mode = .p2nv;
        if (dstF == YUV420P and (srcF == NV12 or srcF == NV21)) c.mode = .nv2p;
        if ((srcF == YUV420P or srcF == YUV422P) and isRGB(dstF) and (dstH & 1) == 0) c.mode = .yuv2rgb;
        if (srcF == BGR24 and dstF == YUV420P and (dstW & 1) == 0) c.mode = .bgr24yv12;
        if (isRGB(srcF) and isRGB(dstF)) c.mode = .rgb2rgb;
        if (srcF == dstF and !isRGB(srcF)) c.mode = .rgb2rgb; // plain copy (not in contract)
    }
    if (c.mode != .generic) {
        fast.setup(c);
        return c;
    }
    try initGeneric(c);
    fast.setup(c);
    return c;
}

fn initGeneric(c: *Ctx) !void {
    const srcW = c.srcW;
    const srcH = c.srcH;
    const dstW = c.dstW;
    const dstH = c.dstH;
    const srcF = c.srcF;
    const dstF = c.dstF;
    var full = false;
    const lumXInc: i32 = @intCast(@divTrunc((@as(i64, srcW) << 16) + (dstW >> 1), dstW));
    const lumYInc: i32 = @intCast(@divTrunc((@as(i64, srcH) << 16) + (dstH >> 1), dstH));
    c.chrSrcHSub = hsub(srcF);
    c.chrSrcVSub = vsub(srcF);
    c.chrDstHSub = hsub(dstF);
    c.chrDstVSub = vsub(dstF);
    if (isRGB(dstF)) {
        if ((dstW & 1) != 0) full = true;
        if (c.chrSrcHSub == 0 and c.chrSrcVSub == 0) full = true;
        if (!full) c.chrDstHSub = 1;
    }
    if (isRGB(srcF) and ((dstW >> c.chrDstHSub) <= (srcW >> 1))) c.chrSrcHSub = 1;
    c.fullChrOut = full;
    c.chrSrcW = ceilShift(srcW, c.chrSrcHSub);
    c.chrSrcH = ceilShift(srcH, c.chrSrcVSub);
    c.chrDstW = ceilShift(dstW, c.chrDstHSub);
    c.chrDstH = ceilShift(dstH, c.chrDstVSub);
    const chrXInc: i32 = @intCast(@divTrunc((@as(i64, c.chrSrcW) << 16) + (c.chrDstW >> 1), c.chrDstW));
    const chrYInc: i32 = @intCast(@divTrunc((@as(i64, c.chrSrcH) << 16) + (c.chrDstH >> 1), c.chrDstH));
    c.needsHc = !(isGray(srcF) or isGray(dstF));
    c.needAlpha = hasAlpha(srcF) and hasAlpha(dstF);
    const srcRange = isGray(srcF);
    const dstRange = isGray(dstF);
    if (srcRange != dstRange and !isRGB(dstF)) {
        c.lumRange = if (srcRange) 2 else 1;
    }

    c.hLum = try initFilter(lumXInc, srcW, dstW, 1 << 14, c.algo, 128, 128);
    c.hChr = try initFilter(chrXInc, c.chrSrcW, c.chrDstW, 1 << 14, c.algo, 128, 128);
    c.vLum = try initFilter(lumYInc, srcH, dstH, 1 << 12, c.algo, 128, 128);
    c.vChr = try initFilter(chrYInc, c.chrSrcH, c.chrDstH, 1 << 12, c.algo, 128, 128);
    c.hasFilters = true;

    c.lumStride = (@as(usize, @intCast(dstW)) + 31) & ~@as(usize, 15);
    c.chrStride = (@as(usize, @intCast(c.chrDstW)) + 31) & ~@as(usize, 15);
    const sh: usize = @intCast(srcH);
    const csh: usize = @intCast(c.chrSrcH);
    c.lumBuf = try alloc.alloc(i16, c.lumStride * sh);
    if (c.needAlpha) c.alpBuf = try alloc.alloc(i16, c.lumStride * sh);
    if (c.needsHc) {
        c.chrUBuf = try alloc.alloc(i16, c.chrStride * csh);
        c.chrVBuf = try alloc.alloc(i16, c.chrStride * csh);
    } else {
        c.chrUBuf = try alloc.alloc(i16, c.chrStride);
        c.chrVBuf = try alloc.alloc(i16, c.chrStride);
        @memset(c.chrUBuf, 1 << 14);
        @memset(c.chrVBuf, 1 << 14);
    }
    const sw: usize = @intCast(srcW);
    c.tmp0 = try alloc.alloc(u16, sw + 64);
    c.tmp1 = try alloc.alloc(u16, sw + 64);
    c.tmp2 = try alloc.alloc(u16, sw + 64);
    c.tmpB0 = try alloc.alloc(u8, sw + 64);
    c.tmpB1 = try alloc.alloc(u8, sw + 64);
}

fn destroyCtx(c: *Ctx) void {
    if (c.hasFilters) {
        freeFilter(&c.hLum);
        freeFilter(&c.hChr);
        freeFilter(&c.vLum);
        freeFilter(&c.vChr);
    }
    if (c.lumBuf.len > 0) alloc.free(c.lumBuf);
    if (c.alpBuf.len > 0) alloc.free(c.alpBuf);
    if (c.chrUBuf.len > 0) alloc.free(c.chrUBuf);
    if (c.chrVBuf.len > 0) alloc.free(c.chrVBuf);
    if (c.tmp0.len > 0) alloc.free(c.tmp0);
    if (c.tmp1.len > 0) alloc.free(c.tmp1);
    if (c.tmp2.len > 0) alloc.free(c.tmp2);
    if (c.tmpB0.len > 0) alloc.free(c.tmpB0);
    if (c.tmpB1.len > 0) alloc.free(c.tmpB1);
    alloc.destroy(c);
}

// ── generic pipeline: scalar reference kernels ─────────────────────────────
pub fn hScale8(dst: []i16, dstW: usize, src: [*]const u8, f: *const Filter) void {
    const fs = f.size;
    for (0..dstW) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, src[p + j]) * f.coef[i * fs + j];
        dst[i] = @intCast(@min(val >> 7, 32767));
    }
}

pub fn hScale16(dst: []i16, dstW: usize, src: [*]const u16, f: *const Filter) void {
    const fs = f.size;
    for (0..dstW) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, src[p + j]) * f.coef[i * fs + j];
        dst[i] = @intCast(@min(val >> 13, 32767));
    }
}

pub fn rgbToY(dst: [*]u16, src: [*]const u8, w: usize, f: i32) void {
    const bpp = rgbBpp(f);
    const ro = rOff(f);
    const bo = bOff(f);
    for (0..w) |i| {
        const r: i32 = src[i * bpp + ro];
        const g: i32 = src[i * bpp + 1];
        const b: i32 = src[i * bpp + bo];
        dst[i] = @intCast((RY * r + GY * g + BY * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUV(du: [*]u16, dv: [*]u16, src: [*]const u8, w: usize, f: i32) void {
    const bpp = rgbBpp(f);
    const ro = rOff(f);
    const bo = bOff(f);
    for (0..w) |i| {
        const r: i32 = src[i * bpp + ro];
        const g: i32 = src[i * bpp + 1];
        const b: i32 = src[i * bpp + bo];
        du[i] = @intCast((RU * r + GU * g + BU * b + (256 << 14) + (1 << 8)) >> 9);
        dv[i] = @intCast((RV * r + GV * g + BV * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

pub fn rgbToUVHalf(du: [*]u16, dv: [*]u16, src: [*]const u8, w: usize, f: i32) void {
    const bpp = rgbBpp(f);
    const ro = rOff(f);
    const bo = bOff(f);
    for (0..w) |i| {
        const r: i32 = @as(i32, src[2 * i * bpp + ro]) + src[(2 * i + 1) * bpp + ro];
        const g: i32 = @as(i32, src[2 * i * bpp + 1]) + src[(2 * i + 1) * bpp + 1];
        const b: i32 = @as(i32, src[2 * i * bpp + bo]) + src[(2 * i + 1) * bpp + bo];
        du[i] = @intCast((RU * r + GU * g + BU * b + (256 << 15) + (1 << 9)) >> 10);
        dv[i] = @intCast((RV * r + GV * g + BV * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

fn lumRangeConv(row: []i16, w: usize, mode: i32) void {
    if (mode == 1) {
        for (row[0..w]) |*v| {
            const x: i32 = @min(@as(i32, v.*), 30189);
            v.* = @intCast((x * 19077 - 39057361) >> 14);
        }
    } else if (mode == 2) {
        for (row[0..w]) |*v| {
            const x: i32 = v.*;
            v.* = @intCast((x * 14071 + 33561947) >> 14);
        }
    }
}

// Horizontal stage for the whole frame.
fn genericHorizontal(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int) void {
    const sw: usize = @intCast(c.srcW);
    const dw: usize = @intCast(c.dstW);
    const sh: usize = @intCast(c.srcH);
    const s0 = src[0].?;
    const st0: isize = ss[0];
    // luma (+alpha)
    for (0..sh) |y| {
        const line = s0 + @as(usize, @intCast(@as(isize, @intCast(y)) * st0));
        const out = c.lumBuf[y * c.lumStride ..];
        if (isRGB(c.srcF)) {
            if (!fast.rgbToYLine(c, c.tmp0.ptr, line, sw)) rgbToY(c.tmp0.ptr, line, sw, c.srcF);
            if (!fast.hScale16Row(c, out, dw, c.tmp0.ptr, &c.hLum)) hScale16(out, dw, c.tmp0.ptr, &c.hLum);
            if (c.needAlpha) {
                for (0..sw) |i| {
                    const a: u16 = line[i * 4 + 3];
                    c.tmp1[i] = (a << 6) | (a >> 2);
                }
                const ao = c.alpBuf[y * c.lumStride ..];
                if (!fast.hScale16Row(c, ao, dw, c.tmp1.ptr, &c.hLum)) hScale16(ao, dw, c.tmp1.ptr, &c.hLum);
            }
        } else {
            if (!fast.hScale8Row(c, out, dw, line, &c.hLum)) hScale8(out, dw, line, &c.hLum);
        }
        if (c.lumRange != 0) lumRangeConv(out, dw, c.lumRange);
    }
    if (!c.needsHc) return;
    const csw: usize = @intCast(c.chrSrcW);
    const cdw: usize = @intCast(c.chrDstW);
    const csh: usize = @intCast(c.chrSrcH);
    for (0..csh) |y| {
        const ou = c.chrUBuf[y * c.chrStride ..];
        const ov = c.chrVBuf[y * c.chrStride ..];
        if (isRGB(c.srcF)) {
            const line = s0 + @as(usize, @intCast(@as(isize, @intCast(y << c.chrSrcVSub)) * st0));
            if (c.chrSrcHSub == 1) {
                if (!fast.rgbToUVHalfLine(c, c.tmp1.ptr, c.tmp2.ptr, line, csw)) rgbToUVHalf(c.tmp1.ptr, c.tmp2.ptr, line, csw, c.srcF);
            } else {
                if (!fast.rgbToUVLine(c, c.tmp1.ptr, c.tmp2.ptr, line, csw)) rgbToUV(c.tmp1.ptr, c.tmp2.ptr, line, csw, c.srcF);
            }
            if (!fast.hScale16Row(c, ou, cdw, c.tmp1.ptr, &c.hChr)) hScale16(ou, cdw, c.tmp1.ptr, &c.hChr);
            if (!fast.hScale16Row(c, ov, cdw, c.tmp2.ptr, &c.hChr)) hScale16(ov, cdw, c.tmp2.ptr, &c.hChr);
        } else if (isSemiPlanar(c.srcF)) {
            const line = src[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[1]));
            const pu = if (c.srcF == NV12) c.tmpB0 else c.tmpB1;
            const pv = if (c.srcF == NV12) c.tmpB1 else c.tmpB0;
            for (0..csw) |i| {
                pu[i] = line[2 * i];
                pv[i] = line[2 * i + 1];
            }
            if (!fast.hScale8Row(c, ou, cdw, c.tmpB0.ptr, &c.hChr)) hScale8(ou, cdw, c.tmpB0.ptr, &c.hChr);
            if (!fast.hScale8Row(c, ov, cdw, c.tmpB1.ptr, &c.hChr)) hScale8(ov, cdw, c.tmpB1.ptr, &c.hChr);
        } else {
            const lu = src[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[1]));
            const lv = src[2].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[2]));
            if (!fast.hScale8Row(c, ou, cdw, lu, &c.hChr)) hScale8(ou, cdw, lu, &c.hChr);
            if (!fast.hScale8Row(c, ov, cdw, lv, &c.hChr)) hScale8(ov, cdw, lv, &c.hChr);
        }
    }
}

inline fn lumRow(c: *Ctx, y: usize) [*]const i16 {
    return c.lumBuf.ptr + y * c.lumStride;
}
inline fn alpRow(c: *Ctx, y: usize) [*]const i16 {
    return c.alpBuf.ptr + y * c.lumStride;
}
inline fn chrURow(c: *Ctx, y: usize) [*]const i16 {
    return if (c.needsHc) c.chrUBuf.ptr + y * c.chrStride else c.chrUBuf.ptr;
}
inline fn chrVRow(c: *Ctx, y: usize) [*]const i16 {
    return if (c.needsHc) c.chrVBuf.ptr + y * c.chrStride else c.chrVBuf.ptr;
}

pub fn planeX(dst: [*]u8, w: usize, rows: []const [*]const i16, coef: []const i16) void {
    if (rows.len == 1) {
        const s = rows[0];
        for (0..w) |i| dst[i] = clipU8((@as(i32, s[i]) + 64) >> 7);
        return;
    }
    for (0..w) |i| {
        var val: i32 = 64 << 12;
        for (rows, 0..) |r, j| val += @as(i32, r[i]) * coef[j];
        dst[i] = clipU8(val >> 19);
    }
}

inline fn writeFull(c: *Ctx, d: [*]u8, Yin: i32, U: i32, V: i32, A: i32, f: i32) void {
    const t = &c.tabs;
    var Y: i32 = Yin - t.y_off;
    Y = Y *% t.y_coeff;
    Y +%= 1 << 21;
    const yu: u32 = @bitCast(Y);
    var R: i32 = @bitCast(yu +% @as(u32, @bitCast(V *% t.v2r)));
    var G: i32 = @bitCast(yu +% @as(u32, @bitCast(V *% t.v2g)) +% @as(u32, @bitCast(U *% t.u2g)));
    var B: i32 = @bitCast(yu +% @as(u32, @bitCast(U *% t.u2b)));
    if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
        R = std.math.clamp(R, 0, (1 << 30) - 1);
        G = std.math.clamp(G, 0, (1 << 30) - 1);
        B = std.math.clamp(B, 0, (1 << 30) - 1);
    }
    d[rOff(f)] = @intCast(R >> 22);
    d[1] = @intCast(G >> 22);
    d[bOff(f)] = @intCast(B >> 22);
    if (rgbBpp(f) == 4) d[3] = @intCast(A);
}

inline fn writeHalf(c: *Ctx, d: [*]u8, Y1: i32, Y2: i32, U: i32, V: i32, f: i32) void {
    const t = &c.tabs;
    const cu: usize = clipU8(U);
    const cv: usize = clipU8(V);
    const ro = t.rv[cv];
    const go = t.gu[cu] + t.gv[cv];
    const bo = t.bu[cu];
    const bpp = rgbBpp(f);
    d[rOff(f)] = t.ytab[clipIdx(ro + Y1)];
    d[1] = t.ytab[clipIdx(go + Y1)];
    d[bOff(f)] = t.ytab[clipIdx(bo + Y1)];
    d[bpp + rOff(f)] = t.ytab[clipIdx(ro + Y2)];
    d[bpp + 1] = t.ytab[clipIdx(go + Y2)];
    d[bpp + bOff(f)] = t.ytab[clipIdx(bo + Y2)];
    if (bpp == 4) {
        d[3] = 255;
        d[7] = 255;
    }
}

fn packedRow(c: *Ctx, dst: [*]u8, dstY: usize) void {
    const f = c.dstF;
    const dw: usize = @intCast(c.dstW);
    const lf = &c.vLum;
    const cf = &c.vChr;
    const cy = dstY >> c.chrDstVSub;
    const lpos: usize = @intCast(lf.pos[dstY]);
    const cpos: usize = @intCast(cf.pos[cy]);
    const lfs = lf.size;
    const cfs = cf.size;
    const lco = lf.coef[dstY * lfs .. dstY * lfs + lfs];
    const cco = cf.coef[cy * cfs .. cy * cfs + cfs];
    const bpp = rgbBpp(f);
    const alpha = c.needAlpha;

    var kind: u8 = 3; // 1: packed1, 2: packed2, 3: X
    var uvalpha: i32 = 0;
    var yalpha: i32 = 0;
    if (lfs == 1 and cfs == 1) {
        kind = 1;
    } else if (lfs == 1 and cfs == 2 and @as(i32, cco[1]) + cco[0] == 4096 and @as(u16, @bitCast(cco[1])) <= 4096) {
        kind = 1;
        uvalpha = cco[1];
    } else if (lfs == 2 and cfs == 2 and @as(i32, lco[1]) + lco[0] == 4096 and @as(u16, @bitCast(lco[1])) <= 4096 and
        @as(i32, cco[1]) + cco[0] == 4096 and @as(u16, @bitCast(cco[1])) <= 4096)
    {
        kind = 2;
        yalpha = lco[1];
        uvalpha = cco[1];
    }
    if (fast.packedRow(c, dst, dstY, kind, yalpha, uvalpha)) return;

    var lrows: [64][*]const i16 = undefined;
    var crowsU: [64][*]const i16 = undefined;
    var crowsV: [64][*]const i16 = undefined;
    var arows: [64][*]const i16 = undefined;
    for (0..lfs) |j| {
        lrows[j] = lumRow(c, lpos + j);
        if (alpha) arows[j] = alpRow(c, lpos + j);
    }
    for (0..cfs) |j| {
        crowsU[j] = chrURow(c, cpos + j);
        crowsV[j] = chrVRow(c, cpos + j);
    }

    if (c.fullChrOut) {
        for (0..dw) |i| {
            var Y: i32 = 0;
            var U: i32 = 0;
            var V: i32 = 0;
            var A: i32 = 255;
            if (kind == 1) {
                Y = @as(i32, lrows[0][i]) * 4;
                if (uvalpha < 2048) {
                    U = (@as(i32, crowsU[0][i]) - (128 << 7)) * 4;
                    V = (@as(i32, crowsV[0][i]) - (128 << 7)) * 4;
                } else {
                    U = (@as(i32, crowsU[0][i]) + crowsU[1][i] - (128 << 8)) * 2;
                    V = (@as(i32, crowsV[0][i]) + crowsV[1][i] - (128 << 8)) * 2;
                }
                if (alpha) {
                    A = (@as(i32, arows[0][i]) + 64) >> 7;
                    if ((A & 0x100) != 0) A = clipU8(A);
                }
            } else if (kind == 2) {
                const ya1 = 4096 - yalpha;
                const ua1 = 4096 - uvalpha;
                Y = (@as(i32, lrows[0][i]) * ya1 + @as(i32, lrows[1][i]) * yalpha) >> 10;
                U = (@as(i32, crowsU[0][i]) * ua1 + @as(i32, crowsU[1][i]) * uvalpha - (128 << 19)) >> 10;
                V = (@as(i32, crowsV[0][i]) * ua1 + @as(i32, crowsV[1][i]) * uvalpha - (128 << 19)) >> 10;
                if (alpha) {
                    A = (@as(i32, arows[0][i]) * ya1 + @as(i32, arows[1][i]) * yalpha + (1 << 18)) >> 19;
                    if ((A & 0x100) != 0) A = clipU8(A);
                }
            } else {
                Y = 1 << 9;
                U = (1 << 9) - (128 << 19);
                V = (1 << 9) - (128 << 19);
                for (0..lfs) |j| Y += @as(i32, lrows[j][i]) * lco[j];
                for (0..cfs) |j| {
                    U += @as(i32, crowsU[j][i]) * cco[j];
                    V += @as(i32, crowsV[j][i]) * cco[j];
                }
                Y >>= 10;
                U >>= 10;
                V >>= 10;
                if (alpha) {
                    A = 1 << 18;
                    for (0..lfs) |j| A += @as(i32, arows[j][i]) * lco[j];
                    A >>= 19;
                    if ((A & 0x100) != 0) A = clipU8(A);
                }
            }
            writeFull(c, dst + i * bpp, Y, U, V, A, f);
        }
    } else {
        const pairs = (dw + 1) >> 1;
        for (0..pairs) |i| {
            var Y1: i32 = 0;
            var Y2: i32 = 0;
            var U: i32 = 0;
            var V: i32 = 0;
            if (kind == 1) {
                Y1 = (@as(i32, lrows[0][2 * i]) + 64) >> 7;
                Y2 = (@as(i32, lrows[0][2 * i + 1]) + 64) >> 7;
                if (uvalpha < 2048) {
                    U = (@as(i32, crowsU[0][i]) + 64) >> 7;
                    V = (@as(i32, crowsV[0][i]) + 64) >> 7;
                } else {
                    U = (@as(i32, crowsU[0][i]) + crowsU[1][i] + 128) >> 8;
                    V = (@as(i32, crowsV[0][i]) + crowsV[1][i] + 128) >> 8;
                }
            } else if (kind == 2) {
                const ya1 = 4096 - yalpha;
                const ua1 = 4096 - uvalpha;
                Y1 = (@as(i32, lrows[0][2 * i]) * ya1 + @as(i32, lrows[1][2 * i]) * yalpha) >> 19;
                Y2 = (@as(i32, lrows[0][2 * i + 1]) * ya1 + @as(i32, lrows[1][2 * i + 1]) * yalpha) >> 19;
                U = (@as(i32, crowsU[0][i]) * ua1 + @as(i32, crowsU[1][i]) * uvalpha) >> 19;
                V = (@as(i32, crowsV[0][i]) * ua1 + @as(i32, crowsV[1][i]) * uvalpha) >> 19;
            } else {
                Y1 = 1 << 18;
                Y2 = 1 << 18;
                U = 1 << 18;
                V = 1 << 18;
                for (0..lfs) |j| {
                    Y1 += @as(i32, lrows[j][2 * i]) * lco[j];
                    Y2 += @as(i32, lrows[j][2 * i + 1]) * lco[j];
                }
                for (0..cfs) |j| {
                    U += @as(i32, crowsU[j][i]) * cco[j];
                    V += @as(i32, crowsV[j][i]) * cco[j];
                }
                Y1 >>= 19;
                Y2 >>= 19;
                U >>= 19;
                V >>= 19;
            }
            writeHalf(c, dst + i * 2 * bpp, Y1, Y2, U, V, f);
        }
    }
}

fn genericVertical(c: *Ctx, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const dh: usize = @intCast(c.dstH);
    const dw: usize = @intCast(c.dstW);
    var rows: [64][*]const i16 = undefined;
    var rows2: [64][*]const i16 = undefined;
    for (0..dh) |y| {
        const d0 = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        if (isRGB(c.dstF)) {
            packedRow(c, d0, y);
            continue;
        }
        // luma
        const lf = &c.vLum;
        const lp: usize = @intCast(lf.pos[y]);
        for (0..lf.size) |j| rows[j] = lumRow(c, lp + j);
        const lco = lf.coef[y * lf.size .. (y + 1) * lf.size];
        if (!fast.planeRow(c, d0, dw, rows[0..lf.size], lco)) planeX(d0, dw, rows[0..lf.size], lco);
        if (isGray(c.dstF)) continue;
        const mask: usize = (@as(usize, 1) << c.chrDstVSub) - 1;
        if ((y & mask) != 0) continue;
        const cy = y >> c.chrDstVSub;
        const cf = &c.vChr;
        const cp: usize = @intCast(cf.pos[cy]);
        for (0..cf.size) |j| {
            rows[j] = chrURow(c, cp + j);
            rows2[j] = chrVRow(c, cp + j);
        }
        const cco = cf.coef[cy * cf.size .. (cy + 1) * cf.size];
        const cdw: usize = @intCast(c.chrDstW);
        if (isSemiPlanar(c.dstF)) {
            const d1 = dst[1].? + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[1]));
            if (!fast.nvRow(c, d1, cdw, rows[0..cf.size], rows2[0..cf.size], cco)) {
                const swap = c.dstF == NV21;
                for (0..cdw) |i| {
                    var u: i32 = 64 << 12;
                    var v: i32 = 64 << 12;
                    for (0..cf.size) |j| {
                        u += @as(i32, rows[j][i]) * cco[j];
                        v += @as(i32, rows2[j][i]) * cco[j];
                    }
                    d1[2 * i + @intFromBool(swap)] = clipU8(u >> 19);
                    d1[2 * i + @intFromBool(!swap)] = clipU8(v >> 19);
                }
            }
        } else {
            const d1 = dst[1].? + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[1]));
            const d2 = dst[2].? + @as(usize, @intCast(@as(isize, @intCast(cy)) * ds[2]));
            // FFmpeg uses yuv2plane1 only for filter size 1; X with coef otherwise
            if (!fast.planeRow(c, d1, cdw, rows[0..cf.size], cco)) planeX(d1, cdw, rows[0..cf.size], cco);
            if (!fast.planeRow(c, d2, cdw, rows2[0..cf.size], cco)) planeX(d2, cdw, rows2[0..cf.size], cco);
        }
    }
}

// ── unscaled special converters ──────────────────────────────────────────────
fn yuv2rgbUnscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.dstW);
    const h: usize = @intCast(c.dstH);
    const is422 = c.srcF == YUV422P;
    const f = c.dstF;
    const bpp = rgbBpp(f);
    const t = &c.tabs;
    for (0..h) |y| {
        const py = src[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const cyy: usize = if (is422) y else y >> 1;
        const pu = src[1].? + @as(usize, @intCast(@as(isize, @intCast(cyy)) * ss[1]));
        const pv = src[2].? + @as(usize, @intCast(@as(isize, @intCast(cyy)) * ss[2]));
        const d = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        if (fast.yuv2rgbRow(c, d, py, pu, pv, w)) continue;
        for (0..w / 2) |i| {
            const U = pu[i];
            const V = pv[i];
            const ro = t.rv[V];
            const go = t.gu[U] + t.gv[V];
            const bo = t.bu[U];
            inline for (0..2) |k| {
                const Y: i32 = py[2 * i + k];
                const o = d + (2 * i + k) * bpp;
                o[rOff(f)] = t.ytab[@intCast(ro + Y)];
                o[1] = t.ytab[@intCast(go + Y)];
                o[bOff(f)] = t.ytab[@intCast(bo + Y)];
                if (bpp == 4) o[3] = 255;
            }
        }
    }
}

fn rgb2rgbUnscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.dstW);
    const h: usize = @intCast(c.dstH);
    if (!isRGB(c.srcF)) {
        // same planar format copy
        const np: usize = if (c.srcF == GRAY8) 1 else if (isSemiPlanar(c.srcF)) 2 else 3;
        for (0..np) |p| {
            const rows = if (p == 0) h else @as(usize, @intCast(ceilShift(c.srcH, vsub(c.srcF))));
            const rb = if (p == 0) w else if (isSemiPlanar(c.srcF)) 2 * @as(usize, @intCast(ceilShift(c.srcW, 1))) else @as(usize, @intCast(ceilShift(c.srcW, hsub(c.srcF))));
            for (0..rows) |y| {
                const s = src[p].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[p]));
                const d = dst[p].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[p]));
                @memcpy(d[0..rb], s[0..rb]);
            }
        }
        return;
    }
    const sf = c.srcF;
    const df = c.dstF;
    const sb = rgbBpp(sf);
    const db = rgbBpp(df);
    for (0..h) |y| {
        const s = src[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const d = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        if (fast.rgb2rgbRow(c, d, s, w)) continue;
        for (0..w) |i| {
            const r = s[i * sb + rOff(sf)];
            const g = s[i * sb + 1];
            const b = s[i * sb + bOff(sf)];
            d[i * db + rOff(df)] = r;
            d[i * db + 1] = g;
            d[i * db + bOff(df)] = b;
            if (db == 4) d[i * db + 3] = if (sb == 4) s[i * sb + 3] else 255;
        }
    }
}

fn p2nvUnscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.srcW);
    const h: usize = @intCast(c.srcH);
    for (0..h) |y| {
        const s = src[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const d = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        @memcpy(d[0..w], s[0..w]);
    }
    const cw: usize = (w + 1) / 2;
    const ch: usize = (h + 1) / 2;
    const swap = c.dstF == NV21;
    for (0..ch) |y| {
        const u = src[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[1]));
        const v = src[2].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[2]));
        const d = dst[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[1]));
        if (swap) fast.interleave(d, v, u, cw) else fast.interleave(d, u, v, cw);
    }
}

fn nv2pUnscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.srcW);
    const h: usize = @intCast(c.srcH);
    for (0..h) |y| {
        const s = src[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const d = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        @memcpy(d[0..w], s[0..w]);
    }
    const cw: usize = (w + 1) / 2;
    const ch: usize = (h + 1) / 2;
    const swap = c.srcF == NV21;
    for (0..ch) |y| {
        const s = src[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[1]));
        const u = dst[1].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[1]));
        const v = dst[2].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[2]));
        if (swap) fast.deinterleave(v, u, s, cw) else fast.deinterleave(u, v, s, cw);
    }
}

fn bgr24yv12Unscaled(c: *Ctx, src: [*]const ?[*]const u8, ss: [*]const c_int, dst: [*]const ?[*]u8, ds: [*]const c_int) void {
    const w: usize = @intCast(c.srcW);
    const h: usize = @intCast(c.srcH);
    const cw = w >> 1;
    var y: usize = 0;
    while (y + 1 < h) : (y += 2) {
        const s1 = src[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ss[0]));
        const s2 = s1 + @as(usize, @intCast(ss[0]));
        const y1 = dst[0].? + @as(usize, @intCast(@as(isize, @intCast(y)) * ds[0]));
        const y2 = y1 + @as(usize, @intCast(ds[0]));
        const ud = dst[1].? + @as(usize, @intCast(@as(isize, @intCast(y >> 1)) * ds[1]));
        const vd = dst[2].? + @as(usize, @intCast(@as(isize, @intCast(y >> 1)) * ds[2]));
        for (0..cw) |i| {
            const b11: i32 = s1[6 * i + 0];
            const g11: i32 = s1[6 * i + 1];
            const r11: i32 = s1[6 * i + 2];
            const b12: i32 = s1[6 * i + 3];
            const g12: i32 = s1[6 * i + 4];
            const r12: i32 = s1[6 * i + 5];
            const b21: i32 = s2[6 * i + 0];
            const g21: i32 = s2[6 * i + 1];
            const r21: i32 = s2[6 * i + 2];
            const b22: i32 = s2[6 * i + 3];
            const g22: i32 = s2[6 * i + 4];
            const r22: i32 = s2[6 * i + 5];
            y1[2 * i] = @truncate(@as(u32, @bitCast(((RY * r11 + GY * g11 + BY * b11) >> 15) + 16)));
            y1[2 * i + 1] = @truncate(@as(u32, @bitCast(((RY * r12 + GY * g12 + BY * b12) >> 15) + 16)));
            y2[2 * i] = @truncate(@as(u32, @bitCast(((RY * r21 + GY * g21 + BY * b21) >> 15) + 16)));
            y2[2 * i + 1] = @truncate(@as(u32, @bitCast(((RY * r22 + GY * g22 + BY * b22) >> 15) + 16)));
            const bx = (b11 + b12 + b21 + b22) >> 2;
            const gx = (g11 + g12 + g21 + g22) >> 2;
            const rx = (r11 + r12 + r21 + r22) >> 2;
            ud[i] = @truncate(@as(u32, @bitCast(((RU * rx + GU * gx + BU * bx) >> 15) + 128)));
            vd[i] = @truncate(@as(u32, @bitCast(((RV * rx + GV * gx + BV * bx) >> 15) + 128)));
        }
    }
}

// ── exports ─────────────────────────────────────────────────────────────────
export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    const c = createCtx(src_w, src_h, src_fmt, dst_w, dst_h, dst_fmt, algo) catch return null;
    return @ptrCast(c);
}

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    switch (c.mode) {
        .yuv2rgb => yuv2rgbUnscaled(c, src_data, src_stride, dst_data, dst_stride),
        .rgb2rgb => rgb2rgbUnscaled(c, src_data, src_stride, dst_data, dst_stride),
        .p2nv => p2nvUnscaled(c, src_data, src_stride, dst_data, dst_stride),
        .nv2p => nv2pUnscaled(c, src_data, src_stride, dst_data, dst_stride),
        .bgr24yv12 => bgr24yv12Unscaled(c, src_data, src_stride, dst_data, dst_stride),
        .generic => {
            if (!fast.genericFused(c, src_data, src_stride, dst_data, dst_stride)) {
                genericHorizontal(c, src_data, src_stride);
                genericVertical(c, dst_data, dst_stride);
            }
        },
    }
    return 0;
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    if (handle) |p| destroyCtx(@ptrCast(@alignCast(p)));
}

