// (v * X) >> 16 (floor) for 0 <= v < 32768, any X: split X = q*65536 + rem
inline fn mulShift16(v: V16i16, X: i64) V16i16 {
    const q: i64 = X >> 16;
    const rem: u32 = @intCast(X - q * 65536);
    const vu: @Vector(16, u32) = @intCast(@as(V16u16, @bitCast(v)));
