fn shufMask(comptime n: usize, comptime sb: usize, comptime db: usize, comptime so: [4]i32) @Vector(n * db, i32) {
    var mk: [n * db]i32 = undefined;
    for (0..n) |p| {
        for (0..db) |k| {
            const s = so[k];
            mk[p * db + k] = if (s < 0) -1 else @as(i32, @intCast(p * sb)) + s;
        }
    }
    return mk;
}

fn convRows(comptime sb: usize, comptime db: usize, comptime so: [4]i32, d: [*]u8, s: [*]const u8, w: usize) void {
    const N = 32;
    const nblk = w / N;
    const ff: @Vector(N * sb, u8) = @splat(255);
    for (0..nblk) |b| {
        const sv: @Vector(N * sb, u8) = s[b * N * sb ..][0 .. N * sb].*;
        const out: @Vector(N * db, u8) = @shuffle(u8, sv, ff, comptime shufMask(N, sb, db, so));
        d[b * N * db ..][0 .. N * db].* = out;
    }
    for (nblk * N..w) |i| {
        for (0..db) |k| {
            const sidx = so[k];
            d[i * db + k] = if (sidx < 0) 255 else s[i * sb + @as(usize, @intCast(sidx))];
        }
    }
