pub fn rgb2rgbRow(c: *Ctx, d: [*]u8, s: [*]const u8, w: usize) bool {
    const sf = c.srcF;
    const df = c.dstF;
    // source byte index for each destination byte; -1 = constant 255 (index into ff vector is ~0 -> use -1)
    const A: i32 = -1;
    switch (sf) {
        m.RGB24 => switch (df) {
            m.BGR24 => convRows(3, 3, .{ 2, 1, 0, 0 }, d, s, w),
            m.RGBA => convRows(3, 4, .{ 0, 1, 2, A }, d, s, w),
            m.BGRA => convRows(3, 4, .{ 2, 1, 0, A }, d, s, w),
            else => return false,
        },
        m.BGR24 => switch (df) {
            m.RGB24 => convRows(3, 3, .{ 2, 1, 0, 0 }, d, s, w),
            m.RGBA => convRows(3, 4, .{ 2, 1, 0, A }, d, s, w),
            m.BGRA => convRows(3, 4, .{ 0, 1, 2, A }, d, s, w),
            else => return false,
        },
        m.RGBA => switch (df) {
            m.RGB24 => convRows(4, 3, .{ 0, 1, 2, 0 }, d, s, w),
            m.BGR24 => convRows(4, 3, .{ 2, 1, 0, 0 }, d, s, w),
            m.BGRA => convRows(4, 4, .{ 2, 1, 0, 3 }, d, s, w),
            else => return false,
        },
        m.BGRA => switch (df) {
            m.RGB24 => convRows(4, 3, .{ 2, 1, 0, 0 }, d, s, w),
            m.BGR24 => convRows(4, 3, .{ 0, 1, 2, 0 }, d, s, w),
            m.RGBA => convRows(4, 4, .{ 2, 1, 0, 3 }, d, s, w),
            else => return false,
        },
        else => return false,
    }
    return true;
}
