// ── horizontal scaling ──
fn isIdentity(f: *const Filter, w: usize, one: i16) bool {
    if (f.size != 1) return false;
    for (0..w) |i| {
        if (f.pos[i] != @as(i32, @intCast(i)) or f.coef[i] != one) return false;
    }
    return true;
}

fn hScaleT(comptime T: type, comptime fs: usize, comptime sh: u5, d: []i16, w: usize, s: [*]const T, f: *const Filter) void {
    const pos = f.pos.ptr;
    const co = f.coef.ptr;
    for (0..w) |i| {
        const p: usize = @intCast(pos[i]);
        var val: i32 = 0;
        inline for (0..fs) |j| val += @as(i32, s[p + j]) * co[i * fs + j];
        d[i] = @intCast(@min(val >> sh, 32767));
    }
}

fn hScaleAny(comptime T: type, comptime sh: u5, d: []i16, w: usize, s: [*]const T, f: *const Filter) void {
    switch (f.size) {
        1 => hScaleT(T, 1, sh, d, w, s, f),
        2 => hScaleT(T, 2, sh, d, w, s, f),
        3 => hScaleT(T, 3, sh, d, w, s, f),
        4 => hScaleT(T, 4, sh, d, w, s, f),
        5 => hScaleT(T, 5, sh, d, w, s, f),
        6 => hScaleT(T, 6, sh, d, w, s, f),
        7 => hScaleT(T, 7, sh, d, w, s, f),
        8 => hScaleT(T, 8, sh, d, w, s, f),
        else => {
            const fs = f.size;
            for (0..w) |i| {
                const p: usize = @intCast(f.pos[i]);
                var val: i32 = 0;
                for (0..fs) |j| val += @as(i32, s[p + j]) * f.coef[i * fs + j];
                d[i] = @intCast(@min(val >> sh, 32767));
            }
        },
    }
}

pub fn hScale16Row(c: *Ctx, d: []i16, w: usize, s: [*]const u16, f: *const Filter) bool {
    const ident = if (f == &c.hLum) c.identL else c.identC;
    if (ident) {
        var i: usize = 0;
        while (i + 16 <= w) : (i += 16) {
            const v: V16u16 = s[i..][0..16].*;
            const x: V16i32 = @intCast(v);
            const y: V16i32 = @min(x * @as(V16i32, @splat(2)), @as(V16i32, @splat(32767)));
            d[i..][0..16].* = @intCast(y);
        }
        while (i < w) : (i += 1) d[i] = @intCast(@min(@as(i32, s[i]) * 2, 32767));
        return true;
    }
    hScaleAny(u16, 13, d, w, s, f);
    return true;
}
pub fn hScale8Row(c: *Ctx, d: []i16, w: usize, s: [*]const u8, f: *const Filter) bool {
    const ident = if (f == &c.hLum) c.identL else c.identC;
    if (ident) {
        var i: usize = 0;
        while (i + 16 <= w) : (i += 16) {
            const v: V16u8 = s[i..][0..16].*;
            const x: V16i16 = @intCast(v);
            d[i..][0..16].* = x << @splat(7);
        }
        while (i < w) : (i += 1) d[i] = @as(i16, s[i]) << 7;
        return true;
    }
    hScaleAny(u8, 7, d, w, s, f);
    return true;
}

// ── packed RGB output ──
inline fn storePix(comptime f: i32, d: [*]u8, r: V16u8, g: V16u8, b: V16u8, a: V16u8) void {
    switch (f) {
        m.RGB24 => store3h(d, r, g, b),
        m.BGR24 => store3h(d, b, g, r),
        m.RGBA => store4h(d, r, g, b, a),
        else => store4h(d, b, g, r, a),
    }
}
fn rgb16Mask() @Vector(48, i32) {
    var mk: [48]i32 = undefined;
    for (0..16) |p| {
        mk[3 * p] = @intCast(2 * p);
        mk[3 * p + 1] = @intCast(2 * p + 1);
        mk[3 * p + 2] = ~@as(i32, @intCast(p));
    }
    return mk;
}
fn quad16Mask() @Vector(64, i32) {
    var mk: [64]i32 = undefined;
    for (0..16) |p| {
        mk[4 * p] = @intCast(2 * p);
        mk[4 * p + 1] = @intCast(2 * p + 1);
        mk[4 * p + 2] = ~@as(i32, @intCast(2 * p));
        mk[4 * p + 3] = ~@as(i32, @intCast(2 * p + 1));
    }
    return mk;
}
inline fn store3h(d: [*]u8, c0: V16u8, c1: V16u8, c2: V16u8) void {
    const p01: V32u8 = @shuffle(u8, c0, c1, pair16Mask());
    const out: @Vector(48, u8) = @shuffle(u8, p01, c2, rgb16Mask());
    d[0..48].* = out;
}
inline fn store4h(d: [*]u8, c0: V16u8, c1: V16u8, c2: V16u8, c3: V16u8) void {
    const p01: V32u8 = @shuffle(u8, c0, c1, pair16Mask());
    const p23: V32u8 = @shuffle(u8, c2, c3, pair16Mask());
    const out: @Vector(64, u8) = @shuffle(u8, p01, p23, quad16Mask());
    d[0..64].* = out;
}

fn fullRowT(comptime f: i32, c: *Ctx, d: [*]u8, w: usize, kind: u8, yalpha: i32, uvalpha: i32,
    lr: []const [*]const i16, cu: []const [*]const i16, cv: []const [*]const i16, ar: []const [*]const i16,
    lco: []const i16, cco: []const i16, alpha: bool) usize {
    const t = &c.tabs;
    const bpp = m.rgbBpp(f);
    var i: usize = 0;
    const yoff: V16i32 = @splat(t.y_off);
    const yc: V16i32 = @splat(t.y_coeff);
    const v2r: V16i32 = @splat(t.v2r);
    const v2g: V16i32 = @splat(t.v2g);
    const u2g: V16i32 = @splat(t.u2g);
    const u2b: V16i32 = @splat(t.u2b);
    const lim: V16i32 = @splat((1 << 30) - 1);
    const zero: V16i32 = @splat(0);
    while (i + 16 <= w) : (i += 16) {
        var Y: V16i32 = undefined;
        var U: V16i32 = undefined;
        var V: V16i32 = undefined;
        var A: V16i32 = @splat(255);
        if (kind == 1) {
            Y = ld16(lr[0] + i) << @splat(2);
            if (uvalpha < 2048) {
                U = (ld16(cu[0] + i) - @as(V16i32, @splat(128 << 7))) << @splat(2);
                V = (ld16(cv[0] + i) - @as(V16i32, @splat(128 << 7))) << @splat(2);
            } else {
                U = (ld16(cu[0] + i) + ld16(cu[1] + i) - @as(V16i32, @splat(128 << 8))) << @splat(1);
                V = (ld16(cv[0] + i) + ld16(cv[1] + i) - @as(V16i32, @splat(128 << 8))) << @splat(1);
            }
            if (alpha) A = (ld16(ar[0] + i) + @as(V16i32, @splat(64))) >> @splat(7);
        } else if (kind == 2) {
            const ya: V16i32 = @splat(yalpha);
            const ya1: V16i32 = @splat(4096 - yalpha);
            const ua: V16i32 = @splat(uvalpha);
            const ua1: V16i32 = @splat(4096 - uvalpha);
            Y = (ld16(lr[0] + i) * ya1 + ld16(lr[1] + i) * ya) >> @splat(10);
            U = (ld16(cu[0] + i) * ua1 + ld16(cu[1] + i) * ua - @as(V16i32, @splat(128 << 19))) >> @splat(10);
            V = (ld16(cv[0] + i) * ua1 + ld16(cv[1] + i) * ua - @as(V16i32, @splat(128 << 19))) >> @splat(10);
            if (alpha) A = (ld16(ar[0] + i) * ya1 + ld16(ar[1] + i) * ya + @as(V16i32, @splat(1 << 18))) >> @splat(19);
        } else {
            Y = vsum(lr, lco, i, 1 << 9) >> @splat(10);
            U = vsum(cu, cco, i, (1 << 9) - (128 << 19)) >> @splat(10);
            V = vsum(cv, cco, i, (1 << 9) - (128 << 19)) >> @splat(10);
            if (alpha) A = vsum(ar, lco, i, 1 << 18) >> @splat(19);
        }
        const Yp = (Y -% yoff) *% yc +% @as(V16i32, @splat(1 << 21));
        const R = @max(@min(Yp +% V *% v2r, lim), zero) >> @splat(22);
        const G = @max(@min(Yp +% V *% v2g +% U *% u2g, lim), zero) >> @splat(22);
        const B = @max(@min(Yp +% U *% u2b, lim), zero) >> @splat(22);
        storePix(f, d + i * bpp, toU8(R), toU8(G), toU8(B), toU8(A));
    }
    return i;
}

pub fn packedRow(c: *Ctx, d: [*]u8, dstY: usize, kind: u8, yalpha: i32, uvalpha: i32) bool {
    if (!c.fullChrOut) return false;
    const dw: usize = @intCast(c.dstW);
    if (dw < 16) return false;
    const lf = &c.vLum;
    const cf = &c.vChr;
    const cy = dstY >> c.chrDstVSub;
    const lpos: usize = @intCast(lf.pos[dstY]);
    const cpos: usize = @intCast(cf.pos[cy]);
    const lfs = lf.size;
    const cfs = cf.size;
    if (lfs > 64 or cfs > 64) return false;
    const lco = lf.coef[dstY * lfs .. dstY * lfs + lfs];
    const cco = cf.coef[cy * cfs .. cy * cfs + cfs];
    var lr: [64][*]const i16 = undefined;
    var ar: [64][*]const i16 = undefined;
    var cu: [64][*]const i16 = undefined;
    var cv: [64][*]const i16 = undefined;
    for (0..lfs) |j| {
        lr[j] = c.lumBuf.ptr + (lpos + j) * c.lumStride;
        if (c.needAlpha) ar[j] = c.alpBuf.ptr + (lpos + j) * c.lumStride;
    }
    for (0..cfs) |j| {
        cu[j] = if (c.needsHc) c.chrUBuf.ptr + (cpos + j) * c.chrStride else c.chrUBuf.ptr;
        cv[j] = if (c.needsHc) c.chrVBuf.ptr + (cpos + j) * c.chrStride else c.chrVBuf.ptr;
    }
    const args = .{ c, d, dw, kind, yalpha, uvalpha, lr[0..lfs], cu[0..cfs], cv[0..cfs], ar[0..lfs], lco, cco, c.needAlpha };
    const done = switch (c.dstF) {
        m.RGB24 => @call(.auto, fullRowT, .{m.RGB24} ++ args),
        m.BGR24 => @call(.auto, fullRowT, .{m.BGR24} ++ args),
        m.RGBA => @call(.auto, fullRowT, .{m.RGBA} ++ args),
        else => @call(.auto, fullRowT, .{m.BGRA} ++ args),
    };
    // finish the tail with the scalar writer: redo the last 16 pixels fully vectorized
    if (done < dw) {
        const bpp = m.rgbBpp(c.dstF);
        const back = dw - 16;
        // recompute last 16 pixels by offsetting all row pointers
        var lr2: [64][*]const i16 = undefined;
        var ar2: [64][*]const i16 = undefined;
        var cu2: [64][*]const i16 = undefined;
        var cv2: [64][*]const i16 = undefined;
        for (0..lfs) |j| {
            lr2[j] = lr[j] + back;
            if (c.needAlpha) ar2[j] = ar[j] + back;
        }
        for (0..cfs) |j| {
            cu2[j] = cu[j] + back;
            cv2[j] = cv[j] + back;
        }
        const args2 = .{ c, d + back * bpp, @as(usize, 16), kind, yalpha, uvalpha, lr2[0..lfs], cu2[0..cfs], cv2[0..cfs], ar2[0..lfs], lco, cco, c.needAlpha };
        _ = switch (c.dstF) {
            m.RGB24 => @call(.auto, fullRowT, .{m.RGB24} ++ args2),
            m.BGR24 => @call(.auto, fullRowT, .{m.BGR24} ++ args2),
            m.RGBA => @call(.auto, fullRowT, .{m.RGBA} ++ args2),
            else => @call(.auto, fullRowT, .{m.BGRA} ++ args2),
        };
    }
    return true;
}
