// ── generic pipeline kernels ────────────────────────────────────────────────
const V8i32 = @Vector(8, i32);

inline fn ld16(p: [*]const i16) V16i32 {
    const v: V16i16 = p[0..16].*;
    return v;
}

inline fn vsum(rows: []const [*]const i16, coef: []const i16, i: usize, init: i32) V16i32 {
    var acc: V16i32 = @splat(init);
    for (rows, 0..) |r, j| acc +%= ld16(r + i) *% @as(V16i32, @splat(@as(i32, coef[j])));
    return acc;
}

inline fn toU8(v: V16i32) V16u8 {
    const cl: V16i32 = @max(@min(v, @as(V16i32, @splat(255))), @as(V16i32, @splat(0)));
    return @truncate(@as(@Vector(16, u32), @bitCast(cl)));
}

pub fn planeRow(c: *Ctx, d: [*]u8, w: usize, rows: []const [*]const i16, coef: []const i16) bool {
    _ = c;
    var i: usize = 0;
    if (rows.len == 1) {
        const r = rows[0];
        while (i + 16 <= w) : (i += 16) {
            d[i..][0..16].* = toU8((ld16(r + i) +% @as(V16i32, @splat(64))) >> @splat(7));
        }
        while (i < w) : (i += 1) d[i] = @intCast(std.math.clamp((@as(i32, r[i]) + 64) >> 7, 0, 255));
        return true;
    }
    while (i + 16 <= w) : (i += 16) {
        d[i..][0..16].* = toU8(vsum(rows, coef, i, 64 << 12) >> @splat(19));
    }
    while (i < w) : (i += 1) {
        var val: i32 = 64 << 12;
        for (rows, 0..) |r, j| val += @as(i32, r[i]) * coef[j];
        d[i] = @intCast(std.math.clamp(val >> 19, 0, 255));
    }
    return true;
}

fn pair16Mask() @Vector(32, i32) {
    var mk: [32]i32 = undefined;
    for (0..16) |p| {
        mk[2 * p] = @intCast(p);
        mk[2 * p + 1] = ~@as(i32, @intCast(p));
    }
    return mk;
}

pub fn nvRow(c: *Ctx, d: [*]u8, w: usize, ru: []const [*]const i16, rv: []const [*]const i16, coef: []const i16) bool {
    const swap = c.dstF == m.NV21;
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const u = toU8(vsum(ru, coef, i, 64 << 12) >> @splat(19));
        const v = toU8(vsum(rv, coef, i, 64 << 12) >> @splat(19));
        const out: V32u8 = if (swap) @shuffle(u8, v, u, pair16Mask()) else @shuffle(u8, u, v, pair16Mask());
        d[2 * i ..][0..32].* = out;
    }
    while (i < w) : (i += 1) {
        var u: i32 = 64 << 12;
        var v: i32 = 64 << 12;
        for (0..coef.len) |j| {
            u += @as(i32, ru[j][i]) * coef[j];
            v += @as(i32, rv[j][i]) * coef[j];
        }
        d[2 * i + @intFromBool(swap)] = @intCast(std.math.clamp(u >> 19, 0, 255));
        d[2 * i + @intFromBool(!swap)] = @intCast(std.math.clamp(v >> 19, 0, 255));
    }
    return true;
}

// ── RGB input conversion ──
fn chanMask(comptime n: usize, comptime bpp: usize, comptime off: usize, comptime step: usize) @Vector(n, i32) {
    var mk: [n]i32 = undefined;
    for (0..n) |p| mk[p] = @intCast(p * step * bpp + off);
    return mk;
}

inline fn loadChan(comptime bpp: usize, comptime off: usize, comptime step: usize, s: [*]const u8) V16i32 {
    const v: @Vector(16 * bpp * step, u8) = s[0 .. 16 * bpp * step].*;
    const ch: V16u8 = @shuffle(u8, v, undefined, chanMask(16, bpp, off, step));
    return ch;
}

fn yLine(comptime bpp: usize, comptime ro: usize, comptime bo: usize, d: [*]u16, s: [*]const u8, w: usize) void {
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const r = loadChan(bpp, ro, 1, s + i * bpp);
        const g = loadChan(bpp, 1, 1, s + i * bpp);
        const b = loadChan(bpp, bo, 1, s + i * bpp);
        const y = (r * @as(V16i32, @splat(m.RY)) + g * @as(V16i32, @splat(m.GY)) + b * @as(V16i32, @splat(m.BY)) + @as(V16i32, @splat((32 << 14) + (1 << 8)))) >> @splat(9);
        d[i..][0..16].* = @truncate(@as(@Vector(16, u32), @bitCast(y)));
    }
    while (i < w) : (i += 1) {
        const r: i32 = s[i * bpp + ro];
        const g: i32 = s[i * bpp + 1];
        const b: i32 = s[i * bpp + bo];
        d[i] = @intCast((m.RY * r + m.GY * g + m.BY * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

fn uvLine(comptime bpp: usize, comptime ro: usize, comptime bo: usize, comptime half: bool, du: [*]u16, dv: [*]u16, s: [*]const u8, w: usize) void {
    const step: usize = if (half) 2 else 1;
    const sh: u5 = if (half) 10 else 9;
    const K: i32 = if (half) (256 << 15) + (1 << 9) else (256 << 14) + (1 << 8);
    var i: usize = 0;
    while (i + 16 <= w) : (i += 16) {
        const base = s + i * bpp * step;
        var r = loadChan(bpp, ro, step, base);
        var g = loadChan(bpp, 1, step, base);
        var b = loadChan(bpp, bo, step, base);
        if (half) {
            r += loadChan(bpp, ro + bpp, step, base);
            g += loadChan(bpp, 1 + bpp, step, base);
            b += loadChan(bpp, bo + bpp, step, base);
        }
        const u = (r * @as(V16i32, @splat(m.RU)) + g * @as(V16i32, @splat(m.GU)) + b * @as(V16i32, @splat(m.BU)) + @as(V16i32, @splat(K))) >> @splat(sh);
        const v = (r * @as(V16i32, @splat(m.RV)) + g * @as(V16i32, @splat(m.GV)) + b * @as(V16i32, @splat(m.BV)) + @as(V16i32, @splat(K))) >> @splat(sh);
        du[i..][0..16].* = @truncate(@as(@Vector(16, u32), @bitCast(u)));
        dv[i..][0..16].* = @truncate(@as(@Vector(16, u32), @bitCast(v)));
    }
    while (i < w) : (i += 1) {
        var r: i32 = s[i * step * bpp + ro];
        var g: i32 = s[i * step * bpp + 1];
        var b: i32 = s[i * step * bpp + bo];
        if (half) {
            r += s[(2 * i + 1) * bpp + ro];
            g += s[(2 * i + 1) * bpp + 1];
            b += s[(2 * i + 1) * bpp + bo];
        }
        du[i] = @intCast((m.RU * r + m.GU * g + m.BU * b + K) >> sh);
        dv[i] = @intCast((m.RV * r + m.GV * g + m.BV * b + K) >> sh);
    }
}

pub fn rgbToYLine(c: *Ctx, d: [*]u16, s: [*]const u8, w: usize) bool {
    switch (c.srcF) {
        m.RGB24 => yLine(3, 0, 2, d, s, w),
        m.BGR24 => yLine(3, 2, 0, d, s, w),
        m.RGBA => yLine(4, 0, 2, d, s, w),
        else => yLine(4, 2, 0, d, s, w),
    }
