        while (i + 16 <= w) : (i += 16) {
            const v: V16u16 = s[i..][0..16].*;
            const x: V16i32 = @intCast(v);
            const y: V16i32 = @min(x * @as(V16i32, @splat(2)), @as(V16i32, @splat(32767)));
