fn rgb16Mask() @Vector(48, i32) {
    var mk: [48]i32 = undefined;
    for (0..16) |p| {
        mk[3 * p] = @intCast(2 * p);
        mk[3 * p + 1] = @intCast(2 * p + 1);
        mk[3 * p + 2] = ~@as(i32, @intCast(p));
