};

pub fn makeGroups(f: *const Filter, w: usize, pf: *const PadFilter) GroupFilter {
    if (pf.fsP != 2 or w < 8) return .{};
    const ng = w / 8;
    const kind = std.heap.c_allocator.alloc(u8, ng) catch return .{};
    var any = false;
    const pa = [8]i32{ 0, 0, 1, 1, 2, 2, 3, 3 };
    const pb = [8]i32{ 0, 1, 1, 2, 2, 3, 3, 4 };
    for (0..ng) |g| {
        var k1 = true;
        var k2 = true;
        var k3 = true;
        for (0..8) |k| {
            const rel = f.pos[g * 8 + k] - f.pos[g * 8];
            if (rel != 2 * @as(i32, @intCast(k))) k1 = false;
            if (rel != pa[k]) k2 = false;
            if (rel != pb[k]) k3 = false;
        }
        kind[g] = if (k1) 1 else if (k2) 2 else if (k3) 3 else 0;
        if (kind[g] != 0) any = true;
    }
    if (!any) {
        std.heap.c_allocator.free(kind);
        return .{};
    }
    return .{ .kind = kind };
